package org.apache.commons.io.channels;

import java.io.IOException;
import java.nio.channels.Channel;

/**
 * Compatibility forwarding class kept in the original package. This class delegates to
 * the implementation in org.apache.commons.io.channels.filter.FilterChannel to preserve
 * existing API after the refactoring that moved the real implementation to the filter
 * subpackage.
 */
public class FilterChannel<C extends Channel> extends org.apache.commons.io.channels.filter.FilterChannel<C> {

    protected FilterChannel(final org.apache.commons.io.channels.filter.FilterChannel.AbstractBuilder<?, ?, ?> builder) throws IOException {
        super(builder);
    }

    /**
     * Constructs a new instance wrapping the given channel.
     */
    public FilterChannel(final C channel) {
        super(channel);
    }

    /**
     * Returns a builder from the moved implementation.
     */
    public static org.apache.commons.io.channels.filter.FilterChannel.Builder forChannel() {
        return org.apache.commons.io.channels.filter.FilterChannel.forChannel();
    }
}

